{
  "complexity": "deep",
  "requiredCapabilities": ["business strategy and risk analysis", "brand strategy and customer experience"],
  "assignments": [
    { "agentId": "business_strategist", "mission": "Using only provided facts, recommend A/B/C for the next 24 months. Compare growth potential, pricing/margin impact, channel conflict, data access, capex/opex, execution risk, exclusivity constraints, and irreversibility. State the strongest counterargument to the chosen path and which reassessed assumptions could flip the decision. Provide crisp decision logic and risk mitigations.", "priority": "high" },
    { "agentId": "brand_creative", "mission": "Assess each option’s effects on premium positioning, price integrity, customer relationship/consultative service, and control of brand experience. Identify risks from discounting and mass exposure, as well as benefits from controlled experiences. Recommend brand safeguards and CX design to mitigate downsides of the chosen path.", "priority": "medium" }
  ],
  "requiresRedTeam": false,
  "reason": "This is a company-level strategy choice needing financial/tradeoff logic and brand/CX implications. External market data is disallowed, so a market researcher adds little. Two specialists can deliver a high-quality, focused recommendation with risks and flip conditions."
}

{
  "complexity": "deep",
  "requiredCapabilities": [
    "Strategic/financial risk assessment and contracting",
    "Creative capacity modeling and governance for brand rollout"
  ],
  "assignments": [
    {
      "agentId": "business_strategist",
      "mission": "Deliver a clear A/B/C recommendation. Weigh strategic upside vs delay/liquidated damages risk. Judge how much PMO + standard templates de-risk execution; assess residual bottleneck from 20% non-standard sites. Define non-negotiable contract terms (wave-based acceptance, penalty caps, exception thresholds, change-control, client 24h SLA). State the single condition most likely to flip the decision.",
      "priority": "high"
    },
    {
      "agentId": "brand_creative",
      "mission": "Build an 18-week approval/capacity model using stated staffing (CD 75%, 2 SDs from wk3, production team). Estimate weekly throughput for standard sites and exception reviews; map critical path for creative approvals and QA; identify queue risks from 20% bespoke sites; recommend governance (triage, escalation, templates) and whether a week-18 full cutover is feasible or phased waves are required.",
      "priority": "high"
    }
  ],
  "requiresRedTeam": false,
  "reason": "Decision hinges on two domains only: strategic/contract risk and creative approval capacity. No external research is allowed or needed. Business strategist integrates the final A/B/C with non-negotiables; brand/creative quantifies throughput and bottlenecks to inform feasibility. This is the minimum sufficient collaboration for a high-stakes contract decision."
}

{
  "complexity": "deep",
  "requiredCapabilities": ["business strategy and financial logic", "brand strategy and architecture"],
  "assignments": [
    { "agentId": "business_strategist", "mission": "Interpret the 9‑month test using only provided data; assess true demand vs promo/store-selection bias; analyze new‑to‑brand flow (56%) and premium upgrade (21%), cannibalization (‑9% premium rev) and net impact; judge scalability and risk; state if evidence justifies a 3‑year nationwide bet; choose A/B/C with rationale and guardrails (if B, outline the 12‑month validation focus).", "priority": "high" },
    { "agentId": "brand_creative", "mission": "Evaluate brand perception shifts (accessibility/price up; ‘professional high‑end’ down; loyalist view stable); assess dilution risk at scale under masterbrand; compare masterbrand vs endorsed sub‑brand trade‑offs and equity protection; determine if shifts are growth evidence, acceptable trade, or warning; advise architecture implications for the chosen A/B/C.", "priority": "medium" }
  ],
  "requiresRedTeam": false,
  "reason": "Board‑level choice needs rigorous data/financial read and brand architecture judgment. No external research is allowed; a market researcher would add little. Two specialists can deliver a defensible recommendation with minimal overlap."
}
